#!/bin/bash

# Keep in sync with lint.sh so the hook and the lint check agree on formatting
PRETTIER=prettier@3.9.10

# Formatting is best effort: report problems on stderr (exit 1 is non-blocking) instead of failing silently
if ! command -v jq >/dev/null 2>&1; then
  echo "format.sh: jq is not installed, file was not formatted" >&2
  exit 1
fi

FILE=$(jq -r '.tool_input.file_path // empty')

case "$FILE" in
  # Seed data is regenerated by reset_data.py and must not pick up formatting diffs
  */data/tasks.json) exit 0 ;;
  *.ts|*.tsx|*.js|*.jsx|*.mjs|*.json|*.css|*.html|*.md)
    if ! command -v npx >/dev/null 2>&1; then
      echo "format.sh: npx is not installed, $FILE was not formatted" >&2
      exit 1
    elif ! out=$(npx --yes "$PRETTIER" --write "$FILE" 2>&1); then
      echo "format.sh: prettier failed on $FILE: $out" >&2
      exit 1
    fi ;;
esac
exit 0
